arguments.command:
curl -s -X POST "https://slack.com/api/users.list" -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/json" -d '{}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERROR:', d); sys.exit(0)
for u in d['members']:
    name=u.get('real_name','')
    if 'diego' in name.lower() or 'alvarez' in name.lower():
        print(u['id'], name, 'DELETED' if u.get('deleted') else '')
print('---all users---')
for u in d['members']:
    print(u['id'], u.get('real_name',''))
"

